fn main() {
    // The IPC dispatcher generated by `tauri::generate_handler!` runs on the main thread and, in
    // unoptimised builds, needs a large stack frame once there are dozens of commands. Windows'
    // default 1 MiB main-thread stack overflows (STATUS_STACK_OVERFLOW), so reserve 8 MiB.
    if std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        println!("cargo:rustc-link-arg-bins=/STACK:8388608");
    }
    tauri_build::build()
}
